use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

/// Upper bound on model rounds, so a model that keeps asking for lookups
/// cannot loop the node forever.
const MAX_ROUNDS: usize = 3;

/// The only tool in scope for this node.
const IN_SCOPE_TOOL: &str = "lookup";

const SYSTEM: &str = "You are a customer-support assistant. Answer the customer's \
question using the supplied knowledge. If you need more information, request the \
`lookup` tool with a short query.";

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(ctx: &ConversationContext, lookups: &[String]) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(intent_label(ctx.intent));
    prompt.push_str("\nQuestion: ");
    prompt.push_str(&ctx.question);
    prompt.push_str("\n\nKnowledge:\n");
    for entry in ctx.knowledge.iter().chain(lookups.iter()) {
        prompt.push_str("- ");
        prompt.push_str(entry);
        prompt.push('\n');
    }
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut lookups: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx, &lookups);

            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != IN_SCOPE_TOOL {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not in scope: {}", req.tool),
                        });
                    }
                    let hits = kb_read::lookup(&req.query);
                    lookups.extend(hits);
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-call budget exhausted".to_string(),
        })
    }
}

export!(Node);
```

